     1→/**
     2→ * Mode Store
     3→ *
     4→ * Manages the application mode: 'daemon' (live) or 'static' (read-only).
     5→ * Detects whether the daemon is reachable and falls back to static JSON if not.
     6→ *
     7→ * AC Coverage:
     8→ * - ac-11 (@gh-pages-export): Fetch JSON snapshot and render
     9→ * - ac-12, ac-13 (@gh-pages-export): Deep linking support
    10→ * - ac-15 (@gh-pages-export): Data freshness indicator
    11→ * - ac-19 (@gh-pages-export): Build flag bypasses daemon check
    12→ * - ac-20 (@gh-pages-export): Base path prefix for snapshot URL
    13→ */
    14→
    15→import type { KspecSnapshot } from '$lib/types/snapshot';
    16→import { DAEMON_API_BASE } from '$lib/constants';
    17→import { base } from '$app/paths';
    18→
    19→// Build-time static mode flag (set via VITE_STATIC_MODE=true)
    20→// When true, skip daemon detection entirely and load static snapshot directly
    21→const BUILD_STATIC_MODE = import.meta.env.VITE_STATIC_MODE === 'true';
    22→
    23→// Application modes
    24→export type AppMode = 'loading' | 'daemon' | 'static';
    25→
    26→// Reactive state
    27→let mode = $state<AppMode>('loading');
    28→let snapshotData = $state<KspecSnapshot | null>(null);
    29→let initError = $state<string | null>(null);
    30→
    31→/**
    32→ * Initialize mode detection
    33→ *
    34→ * 1. If BUILD_STATIC_MODE, load static snapshot directly (no daemon check)
    35→ * 2. Otherwise try daemon health check (2s timeout)
    36→ * 3. Fall back to static JSON
    37→ * 4. Show error state if neither available
    38→ *
    39→ * AC: @gh-pages-export ac-11, ac-19
    40→ */
    41→export async function initMode(): Promise<void> {
    42→	// AC: @gh-pages-export ac-19 - Build flag bypasses daemon check
    43→	if (BUILD_STATIC_MODE) {
    44→		await loadStaticSnapshot();
    45→		return;
    46→	}
    47→
    48→	// 1. Try daemon health check
    49→	try {
    50→		const response = await fetch(`${DAEMON_API_BASE}/health`, {
    51→			signal: AbortSignal.timeout(2000)
    52→		});
    53→		if (response.ok) {
    54→			mode = 'daemon';
    55→			return;
    56→		}
    57→	} catch {
    58→		// Daemon not available, try static fallback
    59→	}
    60→
    61→	// 2. Fall back to static JSON
    62→	// AC: @gh-pages-export ac-11, ac-20 - Fetch kspec-snapshot.json with base path
    63→	try {
    64→		const response = await fetch(`${base}/kspec-snapshot.json`, {
    65→			signal: AbortSignal.timeout(5000)
    66→		});
    67→		if (response.ok) {
    68→			snapshotData = await response.json();
    69→			mode = 'static';
    70→			return;
    71→		}
    72→	} catch {
    73→		// Static JSON not available either
    74→	}
    75→
    76→	// 3. Neither available - default to daemon mode and let connection error handling show message
    77→	mode = 'daemon';
    78→	initError = 'Unable to connect to daemon and no static snapshot available';
    79→}
    80→
    81→/**
    82→ * Load static snapshot with proper base path handling
    83→ * AC: @gh-pages-export ac-19, ac-20
    84→ */
    85→async function loadStaticSnapshot(): Promise<void> {
    86→	try {
    87→		const response = await fetch(`${base}/kspec-snapshot.json`, {
    88→			signal: AbortSignal.timeout(5000)
    89→		});
    90→		if (response.ok) {
    91→			snapshotData = await response.json();
    92→			mode = 'static';
    93→			return;
    94→		}
    95→		console.error('[Mode] Static snapshot fetch failed:', response.status);
    96→	} catch (err) {
    97→		console.error('[Mode] Static snapshot fetch error:', err);
    98→	}
    99→	// If static mode forced but load fails, stay in static mode with error
   100→	// (Don't fall back to daemon - that would cause WebSocket attempts)
   101→	mode = 'static';
   102→	initError = 'Failed to load static snapshot';
   103→}
   104→
   105→/**
   106→ * Check if running in static mode
   107→ * AC: @gh-pages-export ac-11, ac-19
   108→ *
   109→ * Returns true immediately if BUILD_STATIC_MODE is set (synchronous check)
   110→ * to prevent race conditions where API calls run before initMode() completes.
   111→ */
   112→export function isStaticMode(): boolean {
   113→	return BUILD_STATIC_MODE || mode === 'static';
   114→}
   115→
   116→/**
   117→ * Check if running in daemon mode
   118→ */
   119→export function isDaemonMode(): boolean {
   120→	return mode === 'daemon';
   121→}
   122→
   123→/**
   124→ * Check if mode is still loading
   125→ */
   126→export function isLoading(): boolean {
   127→	return mode === 'loading';
   128→}
   129→
   130→/**
   131→ * Get the current mode
   132→ */
   133→export function getMode(): AppMode {
   134→	return mode;
   135→}
   136→
   137→/**
   138→ * Get the loaded snapshot data
   139→ * AC: @gh-pages-export ac-11
   140→ */
   141→export function getSnapshot(): KspecSnapshot | null {
   142→	return snapshotData;
   143→}
   144→
   145→/**
   146→ * Get the export timestamp for freshness display
   147→ * AC: @gh-pages-export ac-15
   148→ */
   149→export function getExportedAt(): string | null {
   150→	return snapshotData?.exported_at ?? null;
   151→}
   152→
   153→/**
   154→ * Get project info from snapshot
   155→ */
   156→export function getSnapshotProject(): { name: string; version?: string } | null {
   157→	return snapshotData?.project ?? null;
   158→}
   159→
   160→/**
   161→ * Get validation info from snapshot
   162→ * AC: @gh-pages-export ac-14
   163→ */
   164→export function getSnapshotValidation(): KspecSnapshot['validation'] | null {
   165→	return snapshotData?.validation ?? null;
   166→}
   167→
   168→/**
   169→ * Get initialization error if any
   170→ */
   171→export function getInitError(): string | null {
   172→	return initError;
   173→}
   174→
   175→/**
   176→ * Read-Only Mode Error
   177→ *
   178→ * Error thrown when a write operation is attempted in static mode.
   179→ * AC: @gh-pages-export ac-18
   180→ */
   181→export class ReadOnlyModeError extends Error {
   182→	constructor(operation: string) {
   183→		super(`Cannot ${operation} in read-only mode. Use the kspec CLI to make changes.`);
   184→		this.name = 'ReadOnlyModeError';
   185→	}
   186→}
   187→
   188→/**
   189→ * Guard for write operations
   190→ * AC: @gh-pages-export ac-18
   191→ */
   192→export function assertWritable(operation: string): void {
   193→	if (isStaticMode()) {
   194→		throw new ReadOnlyModeError(operation);
   195→	}
