  _ulid: string;
  created_at: string;
  author: string;
  content: string;
  supersedes?: string;
}

/**
 * Task todo
 */
export interface Todo {
  _ulid: string;
  content: string;
  status: 'pending' | 'in_progress' | 'completed';
  created_at: string;
}

